// A read-only projection of the owner's ONE Countdown snapshot. No timer is constructed,
// consumed, expired or advanced here; reaching zero never emits an action.
export function sportClockProjection(clock,totalMs,now){
 if(!clock||!numeric(clock.deadline)||clock.pausedMs!==null&&!numeric(clock.pausedMs))return {seconds:null,fraction:null};
 const remaining=Math.max(0,clock.pausedMs??clock.deadline-now);
 return {seconds:Math.ceil(remaining/1000),fraction:numeric(totalMs)&&Number(totalMs)>0?Math.min(1,remaining/Number(totalMs)):null};
}
