 renderJournal(){const journal=this._model.journal,dialog=this.shadowRoot.querySelector('.journal');if(!journal){this._closedJournalKey='';return;}const key=journal.workoutKey+'|'+journal.exerciseId;if(key===this._closedJournalKey)return;if(key===this._journalKey&&dialog.open){this._journalContext=copy(journal);return;}if(this.journalDirty()&&key!==this._journalKey)return;this._journalKey=key;this._journalContext=copy(journal);this._journalDraftId=journal.draftId||this._requestedJournalDraft||crypto.randomUUID();this._journalDraft=copy(journal.sets||journal.today);this._journalBaseline=copy(journal.today);this.journalMarkup();if(!dialog.open)dialog.showModal();}
