 renderSetRows(){const holder=this.shadowRoot.querySelector('.journal-table');holder.innerHTML=this._journalDraft.map((set,index)=>`<div class="set-row"><span>${index+1}</span><label>${unit((this._model.journal||this._journalContext).unit)}<flow-field data-set="${index}" data-part="reps" aria-label="Подход ${index+1}: ${unit((this._model.journal||this._journalContext).unit)}" placeholder="Не записано" value="${esc(set.reps??'')}"></flow-field></label><label>кг<flow-field data-set="${index}" data-part="kilograms" aria-label="Подход ${index+1}: кг" placeholder="Свой вес" value="${esc(set.kilograms??'')}"></flow-field></label><button class="icon" data-remove-set="${index}" aria-label="Убрать подход ${index+1}">×</button></div>`).join('')||'<p class="meta">Сегодня подходы ещё не записаны.</p>';for(const field of holder.querySelectorAll('[data-set]'))field.addEventListener('input',()=>{this._journalDraft[Number(field.dataset.set)][field.dataset.part]=field.value});for(const button of holder.querySelectorAll('[data-remove-set]'))button.onclick=()=>{this._journalDraft.splice(Number(button.dataset.removeSet),1);this.renderSetRows()};}
