 updatePending(){const session=this._model.session,blocked=[...this._pending.values()].some(item=>item.intent.workoutKey===session?.workoutKey&&item.intent.stepKey===session?.stepKey&&['clock','session'].includes(item.intent.kind));for(const button of this.shadowRoot.querySelectorAll('.session [data-clock-action],.session [data-clock-toggle],.session [data-session-action]'))button.disabled=blocked;this.toggleAttribute('aria-busy',this._pending.size>0);}
